import { ChannelType } from '../../types';
/** Parameters of an EQ band */
export type EqBandParam = 'freq' | 'q' | 'gain';
/** High-pass (`hpf`) or low-pass (`lpf`) filter */
export type EqFilterType = 'hpf' | 'lpf';
/** Filter slope in dB/oct */
export type EqFilterSlope = 12 | 24 | 36;
/** Number of parametric EQ bands (`eq.b1` .. `eq.b4`) */
export declare const EQ_BAND_COUNT = 4;
/** Frequency range of the filters */
export declare const EQ_FILTERS: Readonly<Record<EqFilterType, Readonly<{
    minHz: number;
    maxHz: number;
}>>>;
/** State path of the EQ bypass switch, e.g. `i.2.eq.bypass` */
export declare function eqBypassPath(channelId: string): string;
/** State path of an EQ band parameter, e.g. `i.2.eq.b1.freq` */
export declare function eqBandPath(channelId: string, band: number, param: EqBandParam): string;
/** State path of a filter parameter, e.g. `i.2.eq.hpf.freq` */
export declare function eqFilterPath(channelId: string, type: EqFilterType, param: 'freq' | 'slope'): string;
/** Throw if the channel type has no parametric EQ (AUX and VCA channels) */
export declare function assertEqChannelType(type: ChannelType): void;
/** Throw if the channel type has no low-pass filter (only input channels have one) */
export declare function assertLowPassChannelType(type: ChannelType): void;
/** Throw if the band number is not between 1 and 4 */
export declare function assertEqBand(band: number): void;
/** Convert a filter slope (12, 24 or 36 dB/oct) to the raw value `0`, `1` or `2` */
export declare function slopeToValue(slope: EqFilterSlope): number;
/** Convert a raw slope value (`0`, `1` or `2`) to the filter slope in dB/oct */
export declare function valueToSlope(value: number): EqFilterSlope;
